export function withReadingNavigation(html: string) {
  return html
    .replace("default-src 'none';", "default-src 'none'; script-src 'self';")
    .replace(
      '</head>',
      '<link rel="icon" href="/favicon.svg"><script defer src="/read/navigation.js"></script></head>',
    );
}

